r1.lowered_asl:
class.students.count.current = 200
class.students.blue.count.current = percent_of(class.students.count.current, 30)
class.students.not_blue.count.current = (class.students.count.current - class.students.blue.count.current)
class.students.red.count.current = percent_of(class.students.not_blue.count.current, 40)
class.students.yellow.count.current = (class.students.not_blue.count.current - class.students.red.count.current)
queries.result = (class.students.blue.count.current + class.students.yellow.count.current)
RETURN queries.result

